using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud06ARaycast{public static string Main(){var v=Object.FindFirstObjectByType<RailwayOverview>();Canvas.ForceUpdateCanvases();var results=new JArray();foreach(var a in v.Actions){var b=a.Button;var corners=new Vector3[4];((RectTransform)b.transform).GetWorldCorners(corners);var pos=RectTransformUtility.WorldToScreenPoint(null,(corners[0]+corners[2])*.5f);var e=new PointerEventData(EventSystem.current){position=pos};var hits=new System.Collections.Generic.List<RaycastResult>();v.Hud.Raycaster.Raycast(e,hits);results.Add(new JObject{{"id",a.Command},{"pos",pos.ToString()},{"active",b.gameObject.activeInHierarchy},{"raycast",b.targetGraphic.raycastTarget},{"culled",b.targetGraphic.canvasRenderer.cull},{"raycastResults",new JArray(hits.Select(r=>r.gameObject.name))}});}ScreenCapture.CaptureScreenshot("Docs/Measurements/2026-10-02-hud-06a/narrow-inspection.png");return results.ToString();}}
